create table public.v2_stripe_personal_accounts(user_id uuid primary key references auth.users(id),country text not null check(country ~ '^[A-Z]{2}$'),account_id text unique,state text not null check(state in ('onboarding','ready','alternative_required','restricted')),updated_at timestamptz not null default now()); alter table public.v2_stripe_personal_accounts enable row level security; revoke all on public.v2_stripe_personal_accounts from public,anon,authenticated; grant all on public.v2_stripe_personal_accounts to service_role; alter table public.course_payment_recipients add column organisation_id uuid references public.organisations(id),add column recipient_user_id uuid references auth.users(id); create index payment_recipient_company on public.course_payment_recipients(organisation_id); create index payment_recipient_user on public.course_payment_recipients(recipient_user_id); update public.course_payment_recipients r set recipient_user_id=u.id from auth.users u where lower(u.email)=lower(r.recipient_email) and u.email_confirmed_at is not null; create function public.v2_payment_recipient_identity() returns trigger language plpgsql security invoker set search_path='' as $$ declare bound uuid;begin select id into bound from auth.users where lower(email)=lower(new.recipient_email) and email_confirmed_at is not null; new.recipient_user_id=bound; if tg_op='UPDATE' and (new.recipient_user_id,new.organisation_id) is distinct from(old.recipient_user_id,old.organisation_id) and (exists(select 1 from public.course_recipient_allocations where recipient_id=old.id) or exists(select 1 from public.course_recipient_payout_batches where recipient_id=old.id)) then raise exception 'Historical recipient identity cannot be reassigned; create a new recipient record';end if;return new;end $$; create trigger payment_recipient_identity before insert or update of recipient_email,organisation_id on public.course_payment_recipients for each row execute function public.v2_payment_recipient_identity(); create function public.v2_bind_payment_recipient(p_actor uuid) returns void language plpgsql security invoker set search_path='' as $$ declare mailbox text;begin select lower(email) into mailbox from auth.users where id=p_actor and email_confirmed_at is not null; if mailbox is null or not(exists(select 1 from public.user_roles where user_id=p_actor and role in ('admin','reviewer','course_publisher')) or exists(select 1 from public.organisation_memberships where user_id=p_actor and membership_role='owner' and is_active)) then raise exception 'Recipient portal unavailable';end if;update public.course_payment_recipients set recipient_user_id=p_actor where recipient_user_id is null and lower(recipient_email)=mailbox;end $$; revoke all on function public.v2_payment_recipient_identity() from public,anon,authenticated; grant execute on function public.v2_payment_recipient_identity() to service_role; revoke all on function public.v2_bind_payment_recipient(uuid) from public,anon,authenticated; grant execute on function public.v2_bind_payment_recipient(uuid) to service_role;

